cssCode:
html, body, #container {
  margin: 0; width: 100%; height: 100%;
  background: #000; overflow: hidden;
  cursor: pointer;
}
canvas { display: block; }

jsCode:
const el = document.getElementById('container');
const c = document.createElement('canvas');
const ctx = c.getContext('2d');
c.width = el.offsetWidth || 400;
c.height = el.offsetHeight || 500;
el.appendChild(c);
const W = c.width, H = c.height;
const CX = W / 2, CY = H / 2;

let isActive = false;
el.addEventListener('pointerdown', () => isActive = true);
el.addEventListener('pointerup', () => isActive = false);
el.addEventListener('pointerleave', () => isActive = false);

const particles = Array.from({length: 350}, () => {
  return {
    angle: Math.random() * Math.PI * 2,
    radius: Math.random() * Math.min(W, H) * 0.6 + 20,
    speed: (0.005 + Math.random() * 0.015) * (Math.random() < 0.5 ? 1 : -1),
    size: Math.random() * 2 + 0.5,
    hue: 260 + Math.random() * 60,
    alpha: Math.random() * 0.8 + 0.2
  };
});

function draw() {
  ctx.fillStyle = 'rgba(0,0,0,0.08)';
  ctx.fillRect(0, 0, W, H);

  const coreSize = isActive ? 60 : 40;
  const hueShift = isActive ? 180 : 260; // ટચ કરવાથી રંગ બદલાશે

  const grd = ctx.createRadialGradient(CX, CY, 0, CX, CY, coreSize);
  grd.addColorStop(0, `hsla(${hueShift}, 100%, 70%, 0.8)`);
  grd.addColorStop(0.4, `hsla(${hueShift}, 100%, 50%, 0.3)`);
  grd.addColorStop(1, 'transparent');
  ctx.beginPath();
  ctx.arc(CX, CY, coreSize, 0, Math.PI * 2);
  ctx.fillStyle = grd;
  ctx.fill();

  particles.forEach(p => {
    const currentSpeed = isActive ? p.speed * 4 : p.speed; // ઝડપ વધશે
    p.angle += currentSpeed;
    p.radius -= isActive ? 1.5 : 0.2; 

    if (p.radius < 5) {
      p.radius = Math.random() * Math.min(W, H) * 0.6 + coreSize;
      p.angle = Math.random() * Math.PI * 2;
    }

    const x = CX + Math.cos(p.angle) * p.radius;
    const y = CY + Math.sin(p.angle) * p.radius * 0.5;

    ctx.beginPath();
    ctx.arc(x, y, p.size, 0, Math.PI * 2);
    ctx.fillStyle = `hsla(${isActive ? p.hue - 80 : p.hue}, 90%, 70%, ${p.alpha})`;
    ctx.shadowColor = `hsl(${isActive ? p.hue - 80 : p.hue}, 90%, 60%)`;
    ctx.shadowBlur = isActive ? 10 : 6;
    ctx.fill();
  });
  requestAnimationFrame(draw);
}
draw();
